// generated by pipeline/build.js — data desk mollweide world-map widget
const rd = Math.PI / 180

// mollweide forward projection; x in ±2√2, y in ±√2
function proj(lon, lat) {
  const phi = Math.max(-89.9, Math.min(89.9, lat)) * rd
  let t = phi
  for (let i = 0; i < 8; i++) t -= (2 * t + Math.sin(2 * t) - Math.PI * Math.sin(phi)) / (2 + 2 * Math.cos(2 * t))
  return [(2 * Math.SQRT2 / Math.PI) * lon * rd * Math.cos(t), -Math.SQRT2 * Math.sin(t)]
}

function path(pts) {
  let d = '', px = 1e9
  for (const [lon, lat] of pts) {
    const [x, y] = proj(lon, lat)
    d += (Math.abs(x - px) > 1 ? 'M' : 'L') + x.toFixed(2) + ' ' + y.toFixed(2)
    px = x
  }
  return d
}

const range = (a, b, s) => Array.from({ length: (b - a) / s + 1 }, (_, i) => a + i * s)
let _land

// land defaults to dist/land.json next to this module (fetched once)
export async function drawWorldmap(svg, land) {
  land ??= await (_land ??= fetch(new URL('land.json', import.meta.url)).then(r => r.json()))
  svg.setAttribute('viewBox', '-2.9 -1.48 5.8 2.96')
  let grat = ''
  for (const lon of range(-180, 180, 15)) grat += path(range(-90, 90, 5).map(lat => [lon, lat]))
  for (const lat of range(-75, 75, 15)) grat += path(range(-180, 180, 5).map(lon => [lon, lat]))
  const rings = land.rings.map(r => path(r)).join('')
  svg.innerHTML =
    '<path d="' + grat + '" fill="none" stroke="#4D4D4D" stroke-width="0.5" vector-effect="non-scaling-stroke" shape-rendering="crispEdges"/>' +
    '<path d="' + rings + '" fill="none" stroke="#FFFFFF" stroke-opacity="0.7" stroke-width="0.75" vector-effect="non-scaling-stroke"/>' +
    '<g class="boxes"></g>'
}

// boxes: array of [w, s, e, n]; drawn as heavy-stroke empty squares (highlight box)
export function setBoxes(svg, boxes, minSize = 0.12) {
  const g = svg.querySelector('.boxes')
  if (!g) return
  g.innerHTML = boxes.map(([w, s, e, n]) => {
    const [x0, y0] = proj((w + e) / 2, n), [, y1] = proj((w + e) / 2, s)
    const hw = Math.max((proj(e, (s + n) / 2)[0] - proj(w, (s + n) / 2)[0]) / 2, minSize / 2)
    const hh = Math.max((y1 - y0) / 2, minSize / 2)
    const cy = (y0 + y1) / 2
    return '<rect x="' + (x0 - hw).toFixed(2) + '" y="' + (cy - hh).toFixed(2) + '" width="' + (2 * hw).toFixed(2) +
      '" height="' + (2 * hh).toFixed(2) + '" fill="none" stroke="#FFFFFF" stroke-width="1.25" vector-effect="non-scaling-stroke"/>'
  }).join('')
}
